mapper.sql:
WHERE tenant_id = CAST(#{query.tenantId.value} AS BIGINT)
  AND deleted_at IS NULL

    AND status = #{query.status}


    AND risk_level = #{query.riskLevel}


    AND LOWER(source_context) = #{query.sourceContext}


    AND (
        LOWER(title) LIKE #{query.keywordPattern} ESCAPE E'\\'
        OR CAST(source_resource_id AS TEXT) LIKE #{query.keywordPattern} ESCAPE E'\\'
    )
